#!/usr/bin/env python3
"""
Check if 'le' is a valid tag.
"""

from tests.conftest import parse

def test_le_tag():
    """Test if 'le' is a recognized tag."""
    test_cases = [
        "<le>test</le>",         # Basic le tag
        "<light>test</light>",   # light tag
        "<y>test</y>",           # y tag (yellow)
    ]

    for test_case in test_cases:
        print(f"Testing: {repr(test_case)}")
        try:
            result = parse(test_case, strip=False)
            print(f"Success: {repr(result)}")
        except Exception as e:
            print(f"Error: {e}")
        print()

if __name__ == "__main__":
    test_le_tag()

